import type { InstrumentDetails } from "../types";

/**
 * Fictional sample instruments for the demo mode.
 * All names are invented; prices are generated by ./prices.ts.
 * This file and ./prices.ts are the only places that contain demo data.
 */
export interface DemoInstrument extends InstrumentDetails {
  fictional: true;
  /** Price on the anchor date. */
  basePrice: number;
  /** Average daily drift (e.g. 0.0002 = 0.02 %). */
  drift: number;
  /** Sensitivity to the shared "market" movement. */
  beta: number;
  /** Daily instrument-specific volatility (standard deviation). */
  idioVol: number;
}

